insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (1, 1, 'voce-nao-esta-sozinho', 'Você não está sozinho', 'Solidão', 5, 'Oi, [nome]. Esta é a primeira de 20 conversas. Não é aula, não tem nota. São 5 minutos. Pode ler agora ou mais tarde — eu espero.

Jesus contou a história de um filho que pegou a herança do pai, foi embora e perdeu tudo. Quando a fome apertou, ele pensou: "vou voltar, mas só como empregado — não mereço mais ser filho."

A parte que mais importa está em Lucas 15:20:
*"Vinha ele ainda longe, quando seu pai o avistou, e, compadecido dele, correndo, o abraçou e o beijou."*
O pai não esperou o filho chegar. Correu. Antes de qualquer explicação.

Talvez hoje você se sinta como esse filho longe de casa: cansado, sem valor, achando que ninguém correria por você. A Bíblia diz o contrário:
*"Como um pai se compadece de seus filhos, assim o Senhor se compadece dos que o temem."* (Salmo 103:13)

E tem uma promessa que vale para a noite mais escura:
*"Nem a morte, nem a vida, nem o presente, nem o futuro, nem altura, nem profundidade, nem qualquer outra criatura poderá separar-nos do amor de Deus."* (Romanos 8:38-39)
Nada. Nem o que você fez, nem o que você sente.

Se Deus corre na sua direção antes de você explicar qualquer coisa — o que muda em como você se vê hoje?

🎥 Um pastor da Novo Tempo explica em 5 minutos por que o amor de Deus é o antídoto para a ansiedade:
https://www.youtube.com/watch?v=KRteaA6iRPo
*(Pr. Kléber Gonçalves — Rede Novo Tempo)*

Oração de hoje, se quiser dizer com suas palavras: "Deus, se o Senhor corre na minha direção, eu deixo. Vem me buscar onde eu estou."', '[]'::jsonb, 'Deus, se o Senhor corre na minha direção, eu deixo. Vem me buscar onde eu estou.', 'https://www.youtube.com/watch?v=KRteaA6iRPo', 0, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "Oi, [nome]. Esta é a primeira de 20 conversas. Não é aula, não tem nota. São 5 minutos. Pode ler agora ou mais tarde — eu espero."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "Jesus contou a história de um filho que pegou a herança do pai, foi embora e perdeu tudo. Quando a fome apertou, ele pensou: \"vou voltar, mas só como empregado — não mereço mais ser filho.\""}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "A parte que mais importa está em Lucas 15:20:\n*\"Vinha ele ainda longe, quando seu pai o avistou, e, compadecido dele, correndo, o abraçou e o beijou.\"*\nO pai não esperou o filho chegar. Correu. Antes de qualquer explicação."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "Talvez hoje você se sinta como esse filho longe de casa: cansado, sem valor, achando que ninguém correria por você. A Bíblia diz o contrário:\n*\"Como um pai se compadece de seus filhos, assim o Senhor se compadece dos que o temem.\"* (Salmo 103:13)"}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "E tem uma promessa que vale para a noite mais escura:\n*\"Nem a morte, nem a vida, nem o presente, nem o futuro, nem altura, nem profundidade, nem qualquer outra criatura poderá separar-nos do amor de Deus.\"* (Romanos 8:38-39)\nNada. Nem o que você fez, nem o que você sente."}, {"n": 6, "tipo": "reflexao", "rotulo": "para pensar (sem resposta certa)", "texto": "Se Deus corre na sua direção antes de você explicar qualquer coisa — o que muda em como você se vê hoje?"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Um pastor da Novo Tempo explica em 5 minutos por que o amor de Deus é o antídoto para a ansiedade:\nhttps://www.youtube.com/watch?v=KRteaA6iRPo\n*(Pr. Kléber Gonçalves — Rede Novo Tempo)*\n\nOração de hoje, se quiser dizer com suas palavras: \"Deus, se o Senhor corre na minha direção, eu deixo. Vem me buscar onde eu estou.\"", "opcoes": ["Quero a lição 2 amanhã", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 2 amanhã", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=KRteaA6iRPo"]'::jsonb, 'Estudo 2 "Jesus e o Amor Divino" (Lucas 15:11-24; Salmo 103:13-14; Romanos 8:38-39)', NULL)
