insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (2, 1, 'vale-a-pena-continuar-a-vida-tem-dono-e-tem-sentido', 'Vale a pena continuar: a vida tem dono e tem sentido', 'Sem vontade de viver', 5, '[nome], ontem falamos do Pai que corre. Hoje é sobre uma pergunta que muita gente faz baixinho: *"e se eu simplesmente não valer a pena?"*

A resposta da Bíblia é um preço. Deus não deu uma coisa qualquer por você:
*"Porque Deus amou ao mundo de tal maneira que deu o seu Filho unigênito, para que todo o que nele crê não pereça, mas tenha a vida eterna."* (João 3:16)
Ninguém paga tanto por algo sem valor.

E não é um amor que cobra a conta depois. Miqueias 7:18 diz que Deus *"se compraz na misericórdia"* — ou seja, Ele tem *prazer* em perdoar. Não faz de má vontade.

Jesus usou uma imagem simples: *"Se vós, que sois maus, sabeis dar boas dádivas aos vossos filhos, quanto mais vosso Pai, que está nos céus, dará boas coisas aos que lhe pedirem?"* (Mateus 7:11)
Se até pais imperfeitos querem o bem dos filhos, imagine o Pai perfeito.

A frase mais honesta da Bíblia sobre a vida está em Romanos 6:23: *"o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus."*
Salário é o que a gente ganha. Dom é o que a gente recebe de graça. Deus escolheu te dar o segundo.

Alguém pagou o preço mais alto que existe por você. Isso não resolve o que você está vivendo hoje — mas muda quanto você vale. Consegue guardar essa frase por um dia?

🎥 2 minutos sobre o amor de Deus, da Novo Tempo (Igreja Adventista):
https://www.youtube.com/watch?v=AVFVbg86kdM

Oração: "Deus, eu não entendo por que o Senhor pagou tanto por mim. Mas eu aceito. Me ajuda a continuar."', '[]'::jsonb, 'Deus, eu não entendo por que o Senhor pagou tanto por mim. Mas eu aceito. Me ajuda a continuar.', 'https://www.youtube.com/watch?v=AVFVbg86kdM', 0, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], ontem falamos do Pai que corre. Hoje é sobre uma pergunta que muita gente faz baixinho: *\"e se eu simplesmente não valer a pena?\"*"}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "A resposta da Bíblia é um preço. Deus não deu uma coisa qualquer por você:\n*\"Porque Deus amou ao mundo de tal maneira que deu o seu Filho unigênito, para que todo o que nele crê não pereça, mas tenha a vida eterna.\"* (João 3:16)\nNinguém paga tanto por algo sem valor."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "E não é um amor que cobra a conta depois. Miqueias 7:18 diz que Deus *\"se compraz na misericórdia\"* — ou seja, Ele tem *prazer* em perdoar. Não faz de má vontade."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "Jesus usou uma imagem simples: *\"Se vós, que sois maus, sabeis dar boas dádivas aos vossos filhos, quanto mais vosso Pai, que está nos céus, dará boas coisas aos que lhe pedirem?\"* (Mateus 7:11)\nSe até pais imperfeitos querem o bem dos filhos, imagine o Pai perfeito."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "A frase mais honesta da Bíblia sobre a vida está em Romanos 6:23: *\"o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus.\"*\nSalário é o que a gente ganha. Dom é o que a gente recebe de graça. Deus escolheu te dar o segundo."}, {"n": 6, "tipo": "reflexao", "rotulo": "para pensar", "texto": "Alguém pagou o preço mais alto que existe por você. Isso não resolve o que você está vivendo hoje — mas muda quanto você vale. Consegue guardar essa frase por um dia?"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 2 minutos sobre o amor de Deus, da Novo Tempo (Igreja Adventista):\nhttps://www.youtube.com/watch?v=AVFVbg86kdM\n\nOração: \"Deus, eu não entendo por que o Senhor pagou tanto por mim. Mas eu aceito. Me ajuda a continuar.\"", "opcoes": ["Quero a lição 3", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 3", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=AVFVbg86kdM"]'::jsonb, 'Estudo 2 (João 3:16; Miqueias 7:18; Mateus 7:9-11) + Estudo 5 "Jesus e a Salvação" (Romanos 6:23)', NULL)
