insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (3, 1, 'quando-a-vida-doi-deus-na-dor', 'Quando a vida dói: Deus na dor', 'Sofrimento, luto', 5, '[nome], hoje a pergunta é difícil: *se Deus me ama, por que dói tanto?* Não vou te dar uma resposta de para-choque. Vou te mostrar o que a Bíblia diz de verdade.

Jesus contou sobre um fazendeiro que semeou trigo bom. De noite, um inimigo semeou erva daninha no mesmo campo (Mateus 13:24-30). Os empregados perguntaram: *"não semeaste boa semente? De onde vem o joio?"* E o dono respondeu: *"um inimigo fez isso."*

A Bíblia é clara: o mal não veio de Deus. Começou numa rebelião no céu (Apocalipse 12:7-9) e entrou no mundo quando o ser humano escolheu desconfiar de Deus (Gênesis 3). O sofrimento é o joio. *Você não é o joio.* Você é o trigo que está crescendo num campo invadido.

E Deus não ficou assistindo de longe. Ele entrou no campo. Isaías 53:3-4 descreve Jesus assim: *"homem de dores e que sabe o que é padecer… certamente ele tomou sobre si as nossas enfermidades e as nossas dores levou sobre si."*
Ele sabe o que é padecer. Não é teoria.

Por isso o Salmo 34:18 pode prometer: *"Perto está o Senhor dos que têm o coração quebrantado e salva os de espírito oprimido."*
Perto. Não "quando você melhorar". Agora, quebrantado.

De onde veio o joio, na história de Jesus?
A) Da semente ruim do fazendeiro
B) De um inimigo que semeou de noite ✅
C) Da falta de chuva
*(Explicação: o mal tem um autor, e não é Deus nem você.)*

🎥 Consultório de Família (Novo Tempo) — "Como entender a ansiedade e a depressão", com psicólogos e base bíblica, 56 min. Assista aos poucos:
https://www.youtube.com/watch?v=OWKz1bQsw2I

Oração: "Deus, a vida dói. O Senhor sabe o que é isso. Fica perto de mim hoje."', '[{"pergunta": "De onde veio o joio, na história de Jesus?", "alternativas": ["Da semente ruim do fazendeiro", "De um inimigo que semeou de noite", "Da falta de chuva"], "correta": 1, "explicacao": "o mal tem um autor, e não é Deus nem você."}]'::jsonb, 'Deus, a vida dói. O Senhor sabe o que é isso. Fica perto de mim hoje.', 'https://www.youtube.com/watch?v=OWKz1bQsw2I', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], hoje a pergunta é difícil: *se Deus me ama, por que dói tanto?* Não vou te dar uma resposta de para-choque. Vou te mostrar o que a Bíblia diz de verdade."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "Jesus contou sobre um fazendeiro que semeou trigo bom. De noite, um inimigo semeou erva daninha no mesmo campo (Mateus 13:24-30). Os empregados perguntaram: *\"não semeaste boa semente? De onde vem o joio?\"* E o dono respondeu: *\"um inimigo fez isso.\"*"}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "A Bíblia é clara: o mal não veio de Deus. Começou numa rebelião no céu (Apocalipse 12:7-9) e entrou no mundo quando o ser humano escolheu desconfiar de Deus (Gênesis 3). O sofrimento é o joio. *Você não é o joio.* Você é o trigo que está crescendo num campo invadido."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "E Deus não ficou assistindo de longe. Ele entrou no campo. Isaías 53:3-4 descreve Jesus assim: *\"homem de dores e que sabe o que é padecer… certamente ele tomou sobre si as nossas enfermidades e as nossas dores levou sobre si.\"*\nEle sabe o que é padecer. Não é teoria."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Por isso o Salmo 34:18 pode prometer: *\"Perto está o Senhor dos que têm o coração quebrantado e salva os de espírito oprimido.\"*\nPerto. Não \"quando você melhorar\". Agora, quebrantado."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz leve (vale 100 pontos; pode errar)", "texto": "De onde veio o joio, na história de Jesus?\nA) Da semente ruim do fazendeiro\nB) De um inimigo que semeou de noite ✅\nC) Da falta de chuva\n*(Explicação: o mal tem um autor, e não é Deus nem você.)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Consultório de Família (Novo Tempo) — \"Como entender a ansiedade e a depressão\", com psicólogos e base bíblica, 56 min. Assista aos poucos:\nhttps://www.youtube.com/watch?v=OWKz1bQsw2I\n\nOração: \"Deus, a vida dói. O Senhor sabe o que é isso. Fica perto de mim hoje.\"", "opcoes": ["Quero a lição 4", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 4", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=OWKz1bQsw2I"]'::jsonb, 'Estudo 3 "Jesus e a Restauração do Bem" (Mateus 13:24-30; Apocalipse 12:7-10; Romanos 6:23) + Isaías 53:3-4; Salmo 34:18', NULL)
