insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (4, 1, 'paz-para-a-mente-cansada-ansiedade-medo-e-descanso', 'Paz para a mente cansada: ansiedade, medo e descanso', 'Ansiedade, exaustão', 5, '[nome], última conversa do primeiro bloco. Tema: a cabeça que não desliga. A Bíblia tem um remédio que não é mágica — é um lugar para despejar o peso.

*"Confiai nele, ó povo, em todo tempo; derramai perante ele o vosso coração; Deus é o nosso refúgio."* (Salmo 62:8)
"Derramar" é a palavra. Não é fazer uma oração bonita. É virar o balde.

Jesus ensinou a orar escondido: *"entra no teu quarto e, fechada a porta, orarás a teu Pai, que está em secreto."* (Mateus 6:6)
Não precisa de igreja, de palavras certas nem de alguém ouvindo. Precisa de um quarto e de uma porta.

E o que acontece depois de derramar? Filipenses 4:6-7 promete: *"não andeis ansiosos de coisa alguma; em tudo, porém, sejam conhecidas, diante de Deus, as vossas petições… e a paz de Deus, que excede todo o entendimento, guardará o vosso coração e a vossa mente."*
A paz não vem de resolver tudo. Vem de entregar tudo.

Paulo e Silas oraram e cantaram presos, à meia-noite, com as costas abertas de açoite (Atos 16:25). Não porque estava tudo bem. Porque tinham onde despejar. E Jesus convida: *"Vinde a mim, todos os que estais cansados e sobrecarregados, e eu vos aliviarei."* (Mateus 11:28)

Hoje à noite: porta fechada, 2 minutos, diga a Deus em voz baixa as três coisas que mais pesam. Sem enfeitar. Depois me conte só uma palavra de como ficou.

🎥 Consultório de Família (Novo Tempo) — "Como diminuir a ansiedade e a angústia":
https://www.youtube.com/watch?v=8zea0OBzehs

Você concluiu o Bloco I — *Esperança*. 🌱 Ganhou o selo "Esperança" e 400 pontos. O próximo bloco é "Você e Deus": quem é esse Pai que corre, ouve e fica perto.', '[]'::jsonb, NULL, 'https://www.youtube.com/watch?v=8zea0OBzehs', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], última conversa do primeiro bloco. Tema: a cabeça que não desliga. A Bíblia tem um remédio que não é mágica — é um lugar para despejar o peso."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "*\"Confiai nele, ó povo, em todo tempo; derramai perante ele o vosso coração; Deus é o nosso refúgio.\"* (Salmo 62:8)\n\"Derramar\" é a palavra. Não é fazer uma oração bonita. É virar o balde."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "Jesus ensinou a orar escondido: *\"entra no teu quarto e, fechada a porta, orarás a teu Pai, que está em secreto.\"* (Mateus 6:6)\nNão precisa de igreja, de palavras certas nem de alguém ouvindo. Precisa de um quarto e de uma porta."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "E o que acontece depois de derramar? Filipenses 4:6-7 promete: *\"não andeis ansiosos de coisa alguma; em tudo, porém, sejam conhecidas, diante de Deus, as vossas petições… e a paz de Deus, que excede todo o entendimento, guardará o vosso coração e a vossa mente.\"*\nA paz não vem de resolver tudo. Vem de entregar tudo."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Paulo e Silas oraram e cantaram presos, à meia-noite, com as costas abertas de açoite (Atos 16:25). Não porque estava tudo bem. Porque tinham onde despejar. E Jesus convida: *\"Vinde a mim, todos os que estais cansados e sobrecarregados, e eu vos aliviarei.\"* (Mateus 11:28)"}, {"n": 6, "tipo": "exercicio", "rotulo": "exercício de 2 minutos (vale 100 pontos)", "texto": "Hoje à noite: porta fechada, 2 minutos, diga a Deus em voz baixa as três coisas que mais pesam. Sem enfeitar. Depois me conte só uma palavra de como ficou.", "opcoes": ["Fiz", "Vou fazer", "Não consegui"]}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Consultório de Família (Novo Tempo) — \"Como diminuir a ansiedade e a angústia\":\nhttps://www.youtube.com/watch?v=8zea0OBzehs\n\nVocê concluiu o Bloco I — *Esperança*. 🌱 Ganhou o selo \"Esperança\" e 400 pontos. O próximo bloco é \"Você e Deus\": quem é esse Pai que corre, ouve e fica perto.", "opcoes": ["Quero começar o Bloco II", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero começar o Bloco II", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=8zea0OBzehs"]'::jsonb, 'Estudo 4 "Jesus e a Oração" (Salmo 62:8; Mateus 6:6; Mateus 7:7-8; Atos 16:25) + Mateus 11:28; Filipenses 4:6-7', 'Hoje à noite: porta fechada, 2 minutos, diga a Deus em voz baixa as três coisas que mais pesam. Sem enfeitar. Depois me conte só uma palavra de como ficou.')
