insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (5, 2, 'deus-ama-voce-e-sabe-o-seu-nome', 'Deus ama você — e sabe o seu nome', 'Valor próprio', 5, '[nome], bem-vindo(a) ao Bloco II. No primeiro bloco falamos de esperança. Agora vamos conhecer de perto quem é esse Deus — começando por uma coisa simples: Ele sabe o seu nome.

*"Não temas, porque eu te remi; chamei-te pelo teu nome, tu és meu."* (Isaías 43:1)
Não "ei, você". Pelo nome. Num mundo onde a gente vira número, senha e protocolo, Deus chama pelo nome.

O Salmo 139 diz que Deus conhece quando você se senta e quando se levanta, e que *"ainda a palavra me não chegou à língua, e tu, Senhor, já a conheces toda"* (v. 4). Ele sabe o que você não consegue dizer para ninguém.

E não é um Deus que ama porque você rende. A Bíblia resume assim: *"Deus é amor."* (1 João 4:8) Não "Deus tem amor" — Ele *é*. Amar você não é o que Ele faz quando está de bom humor. É quem Ele é.

Esse amor tem um jeito: *"Como um pai se compadece de seus filhos, assim o Senhor se compadece dos que o temem. Pois ele conhece a nossa estrutura e sabe que somos pó."* (Salmo 103:13-14)
Ele sabe do que você é feito. Não espera que você seja de ferro.

Como Deus chama você, segundo Isaías 43:1?
A) Pelo número de inscrição
B) Pelo nome ✅
C) Só quando você acerta
*(Explicação: "chamei-te pelo teu nome, tu és meu".)*

🎥 Está Escrito (TV Novo Tempo) — "Eu tenho medo de Deus": por que tanta gente tem medo de um Deus que é amor?
https://www.youtube.com/watch?v=x9jlwtHXBAk

Oração: "Deus, se o Senhor sabe meu nome, eu respondo: estou aqui. Me ensina a confiar que isso é verdade."', '[{"pergunta": "Como Deus chama você, segundo Isaías 43:1?", "alternativas": ["Pelo número de inscrição", "Pelo nome", "Só quando você acerta"], "correta": 1, "explicacao": "\"chamei-te pelo teu nome, tu és meu\"."}]'::jsonb, 'Deus, se o Senhor sabe meu nome, eu respondo: estou aqui. Me ensina a confiar que isso é verdade.', 'https://www.youtube.com/watch?v=x9jlwtHXBAk', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], bem-vindo(a) ao Bloco II. No primeiro bloco falamos de esperança. Agora vamos conhecer de perto quem é esse Deus — começando por uma coisa simples: Ele sabe o seu nome."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "*\"Não temas, porque eu te remi; chamei-te pelo teu nome, tu és meu.\"* (Isaías 43:1)\nNão \"ei, você\". Pelo nome. Num mundo onde a gente vira número, senha e protocolo, Deus chama pelo nome."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "O Salmo 139 diz que Deus conhece quando você se senta e quando se levanta, e que *\"ainda a palavra me não chegou à língua, e tu, Senhor, já a conheces toda\"* (v. 4). Ele sabe o que você não consegue dizer para ninguém."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "E não é um Deus que ama porque você rende. A Bíblia resume assim: *\"Deus é amor.\"* (1 João 4:8) Não \"Deus tem amor\" — Ele *é*. Amar você não é o que Ele faz quando está de bom humor. É quem Ele é."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Esse amor tem um jeito: *\"Como um pai se compadece de seus filhos, assim o Senhor se compadece dos que o temem. Pois ele conhece a nossa estrutura e sabe que somos pó.\"* (Salmo 103:13-14)\nEle sabe do que você é feito. Não espera que você seja de ferro."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "Como Deus chama você, segundo Isaías 43:1?\nA) Pelo número de inscrição\nB) Pelo nome ✅\nC) Só quando você acerta\n*(Explicação: \"chamei-te pelo teu nome, tu és meu\".)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Está Escrito (TV Novo Tempo) — \"Eu tenho medo de Deus\": por que tanta gente tem medo de um Deus que é amor?\nhttps://www.youtube.com/watch?v=x9jlwtHXBAk\n\nOração: \"Deus, se o Senhor sabe meu nome, eu respondo: estou aqui. Me ensina a confiar que isso é verdade.\"", "opcoes": ["Quero a lição 6 amanhã", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 6 amanhã", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=x9jlwtHXBAk"]'::jsonb, 'Estudo 2 "Jesus e o Amor Divino" (1 João 4:8; Mateus 28:19-20; Salmo 103:13-14) + Isaías 43:1; Salmo 139:1-4, 13-16', NULL)
