insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (6, 2, 'a-oracao-falar-com-alguem-que-ouve', 'A oração: falar com Alguém que ouve', 'Não ter com quem falar', 5, '[nome], na lição 4 você experimentou "virar o balde" com Deus. Hoje vamos entender o que é oração de verdade — porque muita gente acha que é coisa de gente certinha, com palavras certas.

Jesus contou sobre dois homens no templo (Lucas 18:9-14). Um orou listando as próprias qualidades. O outro nem levantava os olhos: *"Ó Deus, sê propício a mim, pecador!"* Jesus disse que foi *esse* que voltou para casa em paz com Deus.
Oração não é discurso. É honestidade.

E não precisa de lugar especial. *"Entra no teu quarto e, fechada a porta, orarás a teu Pai, que está em secreto."* (Mateus 6:6)
Daniel orava três vezes por dia, de janela aberta, mesmo quando isso podia custar a vida dele (Daniel 6:10). Oração vira hábito quando vira refúgio.

Até Jesus orou com medo. Na noite antes da cruz: *"Aba, Pai, tudo te é possível; passa de mim este cálice; contudo, não seja o que eu quero, e sim o que tu queres."* (Marcos 14:36)
Você pode dizer a Deus que não quer passar pelo que está passando. Jesus disse.

A promessa: *"Pedi, e dar-se-vos-á; buscai e achareis; batei, e abrir-se-vos-á."* (Mateus 7:7)
Nem sempre a resposta é a que a gente pediu. Mas a porta nunca é fechada na cara de quem bate.

Dos dois homens no templo, qual voltou em paz com Deus?
A) O que listou as qualidades
B) O que só disse "tem misericórdia de mim" ✅
C) Nenhum dos dois
*(Explicação: Deus ouve honestidade, não currículo.)*

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Oração":
https://www.youtube.com/watch?v=OUKfVkkKcVw

Oração: "Pai, eu não sei orar direito. Mas estou falando. Isso conta?" (Conta.)', '[{"pergunta": "Dos dois homens no templo, qual voltou em paz com Deus?", "alternativas": ["O que listou as qualidades", "O que só disse \"tem misericórdia de mim\"", "Nenhum dos dois"], "correta": 1, "explicacao": "Deus ouve honestidade, não currículo."}]'::jsonb, 'Pai, eu não sei orar direito. Mas estou falando. Isso conta?', 'https://www.youtube.com/watch?v=OUKfVkkKcVw', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], na lição 4 você experimentou \"virar o balde\" com Deus. Hoje vamos entender o que é oração de verdade — porque muita gente acha que é coisa de gente certinha, com palavras certas."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "Jesus contou sobre dois homens no templo (Lucas 18:9-14). Um orou listando as próprias qualidades. O outro nem levantava os olhos: *\"Ó Deus, sê propício a mim, pecador!\"* Jesus disse que foi *esse* que voltou para casa em paz com Deus.\nOração não é discurso. É honestidade."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "E não precisa de lugar especial. *\"Entra no teu quarto e, fechada a porta, orarás a teu Pai, que está em secreto.\"* (Mateus 6:6)\nDaniel orava três vezes por dia, de janela aberta, mesmo quando isso podia custar a vida dele (Daniel 6:10). Oração vira hábito quando vira refúgio."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "Até Jesus orou com medo. Na noite antes da cruz: *\"Aba, Pai, tudo te é possível; passa de mim este cálice; contudo, não seja o que eu quero, e sim o que tu queres.\"* (Marcos 14:36)\nVocê pode dizer a Deus que não quer passar pelo que está passando. Jesus disse."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "A promessa: *\"Pedi, e dar-se-vos-á; buscai e achareis; batei, e abrir-se-vos-á.\"* (Mateus 7:7)\nNem sempre a resposta é a que a gente pediu. Mas a porta nunca é fechada na cara de quem bate."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "Dos dois homens no templo, qual voltou em paz com Deus?\nA) O que listou as qualidades\nB) O que só disse \"tem misericórdia de mim\" ✅\nC) Nenhum dos dois\n*(Explicação: Deus ouve honestidade, não currículo.)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Oração\":\nhttps://www.youtube.com/watch?v=OUKfVkkKcVw\n\nOração: \"Pai, eu não sei orar direito. Mas estou falando. Isso conta?\" (Conta.)", "opcoes": ["Quero a lição 7", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 7", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=OUKfVkkKcVw"]'::jsonb, 'Estudo 4 "Jesus e a Oração" (Lucas 18:9-14; Mateus 6:6; João 14:13-14; Salmo 62:8; Daniel 6:10; Mateus 7:7-8; Marcos 14:36; Tiago 5:16)', NULL)
