insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (7, 2, 'a-biblia-um-livro-para-dias-dificeis', 'A Bíblia: um livro para dias difíceis', 'Onde buscar respostas', 5, '[nome], você já leu seis lições cheias de versículos. Hoje a pergunta é: de onde vem esse livro, e por que dá para confiar nele quando a vida aperta?

Um homem importante da Etiópia voltava de Jerusalém lendo a Bíblia no carro, sem entender nada. Filipe se aproximou e perguntou: *"Compreendes o que vens lendo?"* Ele respondeu: *"Como poderei entender, se alguém não me explicar?"* (Atos 8:30-31)
Não entender de primeira é normal. Por isso você não está lendo sozinho(a).

De onde ela vem? *"Toda a Escritura é inspirada por Deus e útil para o ensino, para a repreensão, para a correção, para a educação na justiça."* (2 Timóteo 3:16)
*"Homens santos falaram da parte de Deus, movidos pelo Espírito Santo."* (2 Pedro 1:21) Não é um livro sobre Deus. É Deus falando.

E ela tem um assunto central. Jesus, depois de ressuscitar, caminhou com dois discípulos e *"começando por Moisés, discorrendo por todos os Profetas, expunha-lhes o que a seu respeito constava em todas as Escrituras."* (Lucas 24:27)
A Bíblia inteira aponta para uma pessoa.

O que ela faz com quem lê? *"Conhecereis a verdade, e a verdade vos libertará."* (João 8:32)
Liberta de mentiras que a gente conta para si mesmo: "não tenho valor", "ninguém se importa", "não tem saída". Cada lição deste curso é a Bíblia desmontando uma dessas.

Segundo Lucas 24:27, sobre quem fala a Bíblia inteira?
A) Sobre regras
B) Sobre Jesus ✅
C) Sobre o povo de Israel apenas
*(Explicação: "o que a seu respeito constava em todas as Escrituras".)*

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Escrituras":
https://www.youtube.com/watch?v=Q7IRoiiI5z8

📖 Desafio opcional para a semana: ler Mateus 5, 6 e 7 (o Sermão do Monte), um capítulo por dia. Se quiser, me conta uma frase que te chamou a atenção.

Oração: "Deus, me ajuda a entender o que leio. E se eu não entender, me manda um Filipe."', '[{"pergunta": "Segundo Lucas 24:27, sobre quem fala a Bíblia inteira?", "alternativas": ["Sobre regras", "Sobre Jesus", "Sobre o povo de Israel apenas"], "correta": 1, "explicacao": "\"o que a seu respeito constava em todas as Escrituras\"."}]'::jsonb, 'Deus, me ajuda a entender o que leio. E se eu não entender, me manda um Filipe.', 'https://www.youtube.com/watch?v=Q7IRoiiI5z8', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], você já leu seis lições cheias de versículos. Hoje a pergunta é: de onde vem esse livro, e por que dá para confiar nele quando a vida aperta?"}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "Um homem importante da Etiópia voltava de Jerusalém lendo a Bíblia no carro, sem entender nada. Filipe se aproximou e perguntou: *\"Compreendes o que vens lendo?\"* Ele respondeu: *\"Como poderei entender, se alguém não me explicar?\"* (Atos 8:30-31)\nNão entender de primeira é normal. Por isso você não está lendo sozinho(a)."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "De onde ela vem? *\"Toda a Escritura é inspirada por Deus e útil para o ensino, para a repreensão, para a correção, para a educação na justiça.\"* (2 Timóteo 3:16)\n*\"Homens santos falaram da parte de Deus, movidos pelo Espírito Santo.\"* (2 Pedro 1:21) Não é um livro sobre Deus. É Deus falando."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "E ela tem um assunto central. Jesus, depois de ressuscitar, caminhou com dois discípulos e *\"começando por Moisés, discorrendo por todos os Profetas, expunha-lhes o que a seu respeito constava em todas as Escrituras.\"* (Lucas 24:27)\nA Bíblia inteira aponta para uma pessoa."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "O que ela faz com quem lê? *\"Conhecereis a verdade, e a verdade vos libertará.\"* (João 8:32)\nLiberta de mentiras que a gente conta para si mesmo: \"não tenho valor\", \"ninguém se importa\", \"não tem saída\". Cada lição deste curso é a Bíblia desmontando uma dessas."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "Segundo Lucas 24:27, sobre quem fala a Bíblia inteira?\nA) Sobre regras\nB) Sobre Jesus ✅\nC) Sobre o povo de Israel apenas\n*(Explicação: \"o que a seu respeito constava em todas as Escrituras\".)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Escrituras\":\nhttps://www.youtube.com/watch?v=Q7IRoiiI5z8\n\n📖 Desafio opcional para a semana: ler Mateus 5, 6 e 7 (o Sermão do Monte), um capítulo por dia. Se quiser, me conta uma frase que te chamou a atenção.\n\nOração: \"Deus, me ajuda a entender o que leio. E se eu não entender, me manda um Filipe.\"", "opcoes": ["Quero a lição 8", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 8", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=Q7IRoiiI5z8"]'::jsonb, 'Estudo 1 "Jesus e as Escrituras Sagradas" (Atos 8:26-40; 2 Pedro 1:21; 2 Timóteo 3:16; João 5:39; Lucas 24:27; João 8:32; João 17:17)', NULL)
on conflict (numero) do update set bloco=excluded.bloco, slug=excluded.slug, titulo=excluded.titulo, necessidade=excluded.necessidade, corpo_md=excluded.corpo_md, quiz=excluded.quiz, oracao=excluded.oracao, video_url=excluded.video_url, pontos=excluded.pontos, publicado=true, mensagens=excluded.mensagens, botoes=excluded.botoes, videos=excluded.videos, fonte=excluded.fonte, exercicio=excluded.exercicio;
insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (8, 2, 'perdao-receber-e-dar', 'Perdão: receber e dar', 'Culpa, mágoa', 5, '[nome], última lição do Bloco II. Tema pesado e necessário: culpa e mágoa. As duas coisas que mais fazem a gente achar que não merece recomeçar.

Primeiro, o perdão que a gente *recebe*. *"Se confessarmos os nossos pecados, ele é fiel e justo para nos perdoar os pecados e nos purificar de toda injustiça."* (1 João 1:9)
Fiel e justo. Não "talvez", não "se você compensar". Confessou, está perdoado.

E se você errar de novo? *"Se alguém pecar, temos Advogado junto ao Pai, Jesus Cristo, o Justo."* (1 João 2:1)
Advogado. Alguém do seu lado quando a sua própria consciência te acusa.

O resultado: *"Justificados, pois, mediante a fé, temos paz com Deus por meio de nosso Senhor Jesus Cristo."* (Romanos 5:1)
Paz com Deus não é sentir-se bem. É saber que a conta está fechada.

Agora, o perdão que a gente *dá*. Pedro perguntou se devia perdoar até sete vezes. Jesus: *"Não te digo que até sete vezes, mas até setenta vezes sete."* (Mateus 18:22)
Perdoar não é dizer que não doeu. É soltar a corda que te prende a quem te feriu. *"Perdoando-vos uns aos outros, como também Deus, em Cristo, vos perdoou."* (Efésios 4:32)

O que 1 João 1:9 diz que acontece quando confessamos?
A) Deus pensa a respeito
B) Deus perdoa e purifica ✅
C) Precisamos compensar primeiro
*(Explicação: "ele é fiel e justo para nos perdoar".)*

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Perdão":
https://www.youtube.com/watch?v=C-ISNiWuB5M

Você concluiu o Bloco II — *Você e Deus*. 🌱 Ganhou o selo "Você e Deus" e mais 400 pontos. O próximo bloco é "Jesus": quem Ele é, o que fez e por que isso muda tudo.

Oração: "Deus, eu entrego o que fiz e o que fizeram comigo. Me perdoa. E me ajuda a soltar."', '[{"pergunta": "O que 1 João 1:9 diz que acontece quando confessamos?", "alternativas": ["Deus pensa a respeito", "Deus perdoa e purifica", "Precisamos compensar primeiro"], "correta": 1, "explicacao": "\"ele é fiel e justo para nos perdoar\"."}]'::jsonb, 'Deus, eu entrego o que fiz e o que fizeram comigo. Me perdoa. E me ajuda a soltar.', 'https://www.youtube.com/watch?v=C-ISNiWuB5M', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], última lição do Bloco II. Tema pesado e necessário: culpa e mágoa. As duas coisas que mais fazem a gente achar que não merece recomeçar."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "Primeiro, o perdão que a gente *recebe*. *\"Se confessarmos os nossos pecados, ele é fiel e justo para nos perdoar os pecados e nos purificar de toda injustiça.\"* (1 João 1:9)\nFiel e justo. Não \"talvez\", não \"se você compensar\". Confessou, está perdoado."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "E se você errar de novo? *\"Se alguém pecar, temos Advogado junto ao Pai, Jesus Cristo, o Justo.\"* (1 João 2:1)\nAdvogado. Alguém do seu lado quando a sua própria consciência te acusa."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "O resultado: *\"Justificados, pois, mediante a fé, temos paz com Deus por meio de nosso Senhor Jesus Cristo.\"* (Romanos 5:1)\nPaz com Deus não é sentir-se bem. É saber que a conta está fechada."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Agora, o perdão que a gente *dá*. Pedro perguntou se devia perdoar até sete vezes. Jesus: *\"Não te digo que até sete vezes, mas até setenta vezes sete.\"* (Mateus 18:22)\nPerdoar não é dizer que não doeu. É soltar a corda que te prende a quem te feriu. *\"Perdoando-vos uns aos outros, como também Deus, em Cristo, vos perdoou.\"* (Efésios 4:32)"}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "O que 1 João 1:9 diz que acontece quando confessamos?\nA) Deus pensa a respeito\nB) Deus perdoa e purifica ✅\nC) Precisamos compensar primeiro\n*(Explicação: \"ele é fiel e justo para nos perdoar\".)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Perdão\":\nhttps://www.youtube.com/watch?v=C-ISNiWuB5M\n\nVocê concluiu o Bloco II — *Você e Deus*. 🌱 Ganhou o selo \"Você e Deus\" e mais 400 pontos. O próximo bloco é \"Jesus\": quem Ele é, o que fez e por que isso muda tudo.\n\nOração: \"Deus, eu entrego o que fiz e o que fizeram comigo. Me perdoa. E me ajuda a soltar.\"", "opcoes": ["Quero começar o Bloco III", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero começar o Bloco III", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=C-ISNiWuB5M"]'::jsonb, 'Estudo 5 "Jesus e a Salvação" (Atos 3:19; Romanos 5:1) + Estudo 6 "Jesus e a Intercessão" (1 João 1:9; 1 João 2:1-2) + Mateus 18:21-22; Efésios 4:32', NULL)
