insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (9, 3, 'jesus-quem-ele-e', 'Jesus: quem Ele é', 'Curiosidade', 5, '[nome], Bloco III. Todo mundo tem uma opinião sobre Jesus: profeta, mestre, homem bom. A Bíblia diz algo maior — e mais próximo.

*"No princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus… E o Verbo se fez carne e habitou entre nós."* (João 1:1, 14)
Deus não mandou um recado. Veio pessoalmente. Nasceu, teve fome, cansou, chorou.

Por isso Ele entende. *"Não temos sumo sacerdote que não possa compadecer-se das nossas fraquezas; antes, foi ele tentado em todas as coisas, à nossa semelhança, mas sem pecado."* (Hebreus 4:15)
Ele sabe o que é ser traído, ficar sozinho, ter medo de morrer.

E o que Ele faz com quem está perdido? Contou a história do pastor que deixa 99 ovelhas para buscar *uma* — e quando acha, *"põe-na sobre os ombros, cheio de júbilo"* (Lucas 15:5).
Ele não manda a ovelha voltar andando. Carrega.

O que Ele oferece: *"Deixo-vos a paz, a minha paz vos dou; não vo-la dou como a dá o mundo. Não se turbe o vosso coração, nem se atemorize."* (João 14:27)
A paz do mundo depende de tudo dar certo. A dEle, não.

O que o pastor faz quando encontra a ovelha perdida (Lucas 15:5)?
A) Manda ela voltar sozinha
B) Põe nos ombros e carrega ✅
C) Dá bronca
*(Explicação: "cheio de júbilo" — Ele fica feliz em carregar você.)*

🎥 Está Escrito Adoração (Rede Novo Tempo) — "A solidão de Jesus": Ele conhece a solidão por dentro.
https://www.youtube.com/watch?v=g5aerZXYFvc

Oração: "Jesus, se o Senhor carrega quem não consegue andar, me carrega hoje."', '[{"pergunta": "O que o pastor faz quando encontra a ovelha perdida (Lucas 15:5)?", "alternativas": ["Manda ela voltar sozinha", "Põe nos ombros e carrega", "Dá bronca"], "correta": 1, "explicacao": "\"cheio de júbilo\" — Ele fica feliz em carregar você."}]'::jsonb, 'Jesus, se o Senhor carrega quem não consegue andar, me carrega hoje.', 'https://www.youtube.com/watch?v=g5aerZXYFvc', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], Bloco III. Todo mundo tem uma opinião sobre Jesus: profeta, mestre, homem bom. A Bíblia diz algo maior — e mais próximo."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "*\"No princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus… E o Verbo se fez carne e habitou entre nós.\"* (João 1:1, 14)\nDeus não mandou um recado. Veio pessoalmente. Nasceu, teve fome, cansou, chorou."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "Por isso Ele entende. *\"Não temos sumo sacerdote que não possa compadecer-se das nossas fraquezas; antes, foi ele tentado em todas as coisas, à nossa semelhança, mas sem pecado.\"* (Hebreus 4:15)\nEle sabe o que é ser traído, ficar sozinho, ter medo de morrer."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "E o que Ele faz com quem está perdido? Contou a história do pastor que deixa 99 ovelhas para buscar *uma* — e quando acha, *\"põe-na sobre os ombros, cheio de júbilo\"* (Lucas 15:5).\nEle não manda a ovelha voltar andando. Carrega."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "O que Ele oferece: *\"Deixo-vos a paz, a minha paz vos dou; não vo-la dou como a dá o mundo. Não se turbe o vosso coração, nem se atemorize.\"* (João 14:27)\nA paz do mundo depende de tudo dar certo. A dEle, não."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "O que o pastor faz quando encontra a ovelha perdida (Lucas 15:5)?\nA) Manda ela voltar sozinha\nB) Põe nos ombros e carrega ✅\nC) Dá bronca\n*(Explicação: \"cheio de júbilo\" — Ele fica feliz em carregar você.)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Está Escrito Adoração (Rede Novo Tempo) — \"A solidão de Jesus\": Ele conhece a solidão por dentro.\nhttps://www.youtube.com/watch?v=g5aerZXYFvc\n\nOração: \"Jesus, se o Senhor carrega quem não consegue andar, me carrega hoje.\"", "opcoes": ["Quero a lição 10", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 10", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=g5aerZXYFvc"]'::jsonb, 'Estudo 1 (João 1:1-4, 14; Mateus 8:8-10) + Estudo 5 (João 14:27; Lucas 15:3-7) + Hebreus 4:15', NULL)
