insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (10, 3, 'a-cruz-o-preco-do-amor', 'A cruz: o preço do amor', 'Culpa', 5, '[nome], hoje é o centro de tudo. Se você só guardar uma lição do curso inteiro, que seja esta.

O problema: *"Todos pecaram e carecem da glória de Deus."* (Romanos 3:23) Todos. Não é sobre ser pior que os outros. É sobre ser humano. E a gente não consegue se limpar sozinho: *"Ainda que te laves com salitre e amontoes sabão, a mancha da tua iniquidade está diante de mim."* (Jeremias 2:22)

A solução não veio de nós: *"Assim como, por uma só ofensa, veio o juízo sobre todos os homens para condenação, assim também, por um só ato de justiça, veio a graça sobre todos os homens para a justificação que dá vida."* (Romanos 5:18)
Um ato. Uma cruz. Para todos.

E como se recebe? *"Pela graça sois salvos, mediante a fé; e isto não vem de vós; é dom de Deus."* (Efésios 2:8)
Dom = presente. Presente não se paga, não se merece, não se ganha por bom comportamento. Se aceita.

A resposta nossa é simples: *"Arrependei-vos, pois, e convertei-vos para serem cancelados os vossos pecados."* (Atos 3:19)
Arrepender é virar o rosto para Deus. E o resultado: *"Se alguém está em Cristo, é nova criatura; as coisas antigas já passaram; eis que se fizeram novas."* (2 Coríntios 5:17)
Nova criatura. Não "versão melhorada". Nova.

Segundo Efésios 2:8, a salvação é:
A) Um salário por bom comportamento
B) Um presente, recebido pela fé ✅
C) Para quem nunca errou
*(Explicação: "é dom de Deus" — presente.)*

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Salvação":
https://www.youtube.com/watch?v=O9Hy-k3whtI

💛 Se quiser, hoje é um bom dia para dizer: "Jesus, eu aceito o Senhor como meu Salvador." Não precisa de cerimônia. Se disser, me conta — alguém da igreja vai orar com você. Se ainda não, tudo bem. Vamos continuar.', '[{"pergunta": "Segundo Efésios 2:8, a salvação é:", "alternativas": ["Um salário por bom comportamento", "Um presente, recebido pela fé", "Para quem nunca errou"], "correta": 1, "explicacao": "\"é dom de Deus\" — presente."}]'::jsonb, NULL, 'https://www.youtube.com/watch?v=O9Hy-k3whtI', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], hoje é o centro de tudo. Se você só guardar uma lição do curso inteiro, que seja esta."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "O problema: *\"Todos pecaram e carecem da glória de Deus.\"* (Romanos 3:23) Todos. Não é sobre ser pior que os outros. É sobre ser humano. E a gente não consegue se limpar sozinho: *\"Ainda que te laves com salitre e amontoes sabão, a mancha da tua iniquidade está diante de mim.\"* (Jeremias 2:22)"}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "A solução não veio de nós: *\"Assim como, por uma só ofensa, veio o juízo sobre todos os homens para condenação, assim também, por um só ato de justiça, veio a graça sobre todos os homens para a justificação que dá vida.\"* (Romanos 5:18)\nUm ato. Uma cruz. Para todos."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "E como se recebe? *\"Pela graça sois salvos, mediante a fé; e isto não vem de vós; é dom de Deus.\"* (Efésios 2:8)\nDom = presente. Presente não se paga, não se merece, não se ganha por bom comportamento. Se aceita."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "A resposta nossa é simples: *\"Arrependei-vos, pois, e convertei-vos para serem cancelados os vossos pecados.\"* (Atos 3:19)\nArrepender é virar o rosto para Deus. E o resultado: *\"Se alguém está em Cristo, é nova criatura; as coisas antigas já passaram; eis que se fizeram novas.\"* (2 Coríntios 5:17)\nNova criatura. Não \"versão melhorada\". Nova."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "Segundo Efésios 2:8, a salvação é:\nA) Um salário por bom comportamento\nB) Um presente, recebido pela fé ✅\nC) Para quem nunca errou\n*(Explicação: \"é dom de Deus\" — presente.)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Salvação\":\nhttps://www.youtube.com/watch?v=O9Hy-k3whtI\n\n💛 Se quiser, hoje é um bom dia para dizer: \"Jesus, eu aceito o Senhor como meu Salvador.\" Não precisa de cerimônia. Se disser, me conta — alguém da igreja vai orar com você. Se ainda não, tudo bem. Vamos continuar.", "opcoes": ["Eu aceitei", "Quero a lição 11", "Quero falar com uma pessoa"]}]'::jsonb, '["Eu aceitei", "Quero a lição 11", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=O9Hy-k3whtI"]'::jsonb, 'Estudo 5 "Jesus e a Salvação" (Romanos 5:12; Jeremias 2:22; Romanos 5:17-19; Efésios 2:8; Atos 3:19; Romanos 3:23; 2 Coríntios 5:17)', NULL)
on conflict (numero) do update set bloco=excluded.bloco, slug=excluded.slug, titulo=excluded.titulo, necessidade=excluded.necessidade, corpo_md=excluded.corpo_md, quiz=excluded.quiz, oracao=excluded.oracao, video_url=excluded.video_url, pontos=excluded.pontos, publicado=true, mensagens=excluded.mensagens, botoes=excluded.botoes, videos=excluded.videos, fonte=excluded.fonte, exercicio=excluded.exercicio;
insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (11, 3, 'a-ressurreicao-e-a-vida-que-vence-a-morte', 'A ressurreição e a vida que vence a morte', 'Medo da morte', 5, '[nome], Jesus tinha um amigo chamado Lázaro. Lázaro morreu. Jesus chegou quatro dias depois — e a Bíblia registra o versículo mais curto e mais humano: *"Jesus chorou."* (João 11:35)

Antes de fazer qualquer milagre, Ele chorou com as irmãs. Deus não pula o luto. Ele entra nele.

Depois disse a Marta: *"Eu sou a ressurreição e a vida. Quem crê em mim, ainda que morra, viverá."* (João 11:25)
E chamou Lázaro pelo nome. E Lázaro saiu.

Isso não foi um caso isolado. Foi um ensaio. *"Cristo ressuscitou dentre os mortos, sendo ele as primícias dos que dormem… Pois assim como, em Adão, todos morrem, assim também todos serão vivificados em Cristo."* (1 Coríntios 15:20, 22)
Primícias = o primeiro de uma colheita. Se Ele voltou, os dEle voltam.

Por isso o cristão pode olhar para a morte sem desespero. Não porque ela não dói. Porque ela não tem a última palavra. *"Se alguém guardar a minha palavra, nunca verá a morte."* (João 8:51)

O que Jesus fez antes de ressuscitar Lázaro?
A) Repreendeu as irmãs por chorar
B) Chorou com elas ✅
C) Foi embora
*(Explicação: Deus não pula o luto.)*

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Ressurreição":
https://www.youtube.com/watch?v=p8Wszj7kUXA

Se você perdeu alguém, eu sinto muito. Se quiser, me conta o nome. Alguém da igreja vai orar por você com esse nome.', '[{"pergunta": "O que Jesus fez antes de ressuscitar Lázaro?", "alternativas": ["Repreendeu as irmãs por chorar", "Chorou com elas", "Foi embora"], "correta": 1, "explicacao": "Deus não pula o luto."}]'::jsonb, NULL, 'https://www.youtube.com/watch?v=p8Wszj7kUXA', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], Jesus tinha um amigo chamado Lázaro. Lázaro morreu. Jesus chegou quatro dias depois — e a Bíblia registra o versículo mais curto e mais humano: *\"Jesus chorou.\"* (João 11:35)"}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "Antes de fazer qualquer milagre, Ele chorou com as irmãs. Deus não pula o luto. Ele entra nele."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "Depois disse a Marta: *\"Eu sou a ressurreição e a vida. Quem crê em mim, ainda que morra, viverá.\"* (João 11:25)\nE chamou Lázaro pelo nome. E Lázaro saiu."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "Isso não foi um caso isolado. Foi um ensaio. *\"Cristo ressuscitou dentre os mortos, sendo ele as primícias dos que dormem… Pois assim como, em Adão, todos morrem, assim também todos serão vivificados em Cristo.\"* (1 Coríntios 15:20, 22)\nPrimícias = o primeiro de uma colheita. Se Ele voltou, os dEle voltam."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Por isso o cristão pode olhar para a morte sem desespero. Não porque ela não dói. Porque ela não tem a última palavra. *\"Se alguém guardar a minha palavra, nunca verá a morte.\"* (João 8:51)"}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "O que Jesus fez antes de ressuscitar Lázaro?\nA) Repreendeu as irmãs por chorar\nB) Chorou com elas ✅\nC) Foi embora\n*(Explicação: Deus não pula o luto.)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Ressurreição\":\nhttps://www.youtube.com/watch?v=p8Wszj7kUXA\n\nSe você perdeu alguém, eu sinto muito. Se quiser, me conta o nome. Alguém da igreja vai orar por você com esse nome.", "opcoes": ["Quero a lição 12", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 12", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=p8Wszj7kUXA"]'::jsonb, 'Estudo 8 "Jesus e a Vida Eterna" (João 11:1-45; João 11:25; 1 Coríntios 15:20-22) + Estudo 5 (1 Coríntios 15:20-22; João 8:51)', NULL)
on conflict (numero) do update set bloco=excluded.bloco, slug=excluded.slug, titulo=excluded.titulo, necessidade=excluded.necessidade, corpo_md=excluded.corpo_md, quiz=excluded.quiz, oracao=excluded.oracao, video_url=excluded.video_url, pontos=excluded.pontos, publicado=true, mensagens=excluded.mensagens, botoes=excluded.botoes, videos=excluded.videos, fonte=excluded.fonte, exercicio=excluded.exercicio;
insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (12, 3, 'a-graca-que-transforma', 'A graça que transforma', 'Vergonha, recomeço', 5, '[nome], última lição do Bloco III. Pergunta comum: "eu aceitei Jesus, mas continuo o mesmo. E agora?" A Bíblia tem uma imagem para isso.

*"Eu sou a videira, vós, os ramos. Quem permanece em mim, e eu, nele, esse dá muito fruto; porque sem mim nada podeis fazer."* (João 15:5)
O ramo não se esforça para dar uva. Fica ligado. A seiva faz o resto.

A mudança é obra dEle: *"Ele nos libertou do império das trevas e nos transportou para o reino do Filho do seu amor."* (Colossenses 1:13)
Transportou. Você não atravessou a pé. Foi levado.

E o fruto aparece devagar: *"O fruto do Espírito é: amor, alegria, paz, longanimidade, benignidade, bondade, fidelidade, mansidão, domínio próprio."* (Gálatas 5:22-23)
Fruto não aparece no dia seguinte ao plantio. Mas aparece.

Vai ter luta. *"A nossa luta não é contra o sangue e a carne, e sim contra… as forças espirituais do mal."* (Efésios 6:12) Por isso Deus dá armadura: verdade, justiça, fé, salvação, a Palavra (Efésios 6:14-17). Você não briga desarmado(a).

Como o ramo dá fruto, segundo João 15:5?
A) Se esforçando muito
B) Permanecendo ligado à videira ✅
C) Sozinho
*(Explicação: "sem mim nada podeis fazer".)*

🎥 Consultório de Família (Novo Tempo) — "Quando o outro não quer mudar": sobre transformação que não se força.
https://www.youtube.com/watch?v=A7PgC6nQByw

Você concluiu o Bloco III — *Jesus*. 🌱 Selo "Jesus" + 400 pontos. Faltam dois blocos. O próximo, "Uma vida inteira", é sobre corpo, descanso, família e pertencer a algum lugar.

Oração: "Jesus, me mantém ligado(a) ao Senhor. Eu não dou conta de produzir fruto sozinho(a)."', '[{"pergunta": "Como o ramo dá fruto, segundo João 15:5?", "alternativas": ["Se esforçando muito", "Permanecendo ligado à videira", "Sozinho"], "correta": 1, "explicacao": "\"sem mim nada podeis fazer\"."}]'::jsonb, 'Jesus, me mantém ligado(a) ao Senhor. Eu não dou conta de produzir fruto sozinho(a).', 'https://www.youtube.com/watch?v=A7PgC6nQByw', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], última lição do Bloco III. Pergunta comum: \"eu aceitei Jesus, mas continuo o mesmo. E agora?\" A Bíblia tem uma imagem para isso."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "*\"Eu sou a videira, vós, os ramos. Quem permanece em mim, e eu, nele, esse dá muito fruto; porque sem mim nada podeis fazer.\"* (João 15:5)\nO ramo não se esforça para dar uva. Fica ligado. A seiva faz o resto."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "A mudança é obra dEle: *\"Ele nos libertou do império das trevas e nos transportou para o reino do Filho do seu amor.\"* (Colossenses 1:13)\nTransportou. Você não atravessou a pé. Foi levado."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "E o fruto aparece devagar: *\"O fruto do Espírito é: amor, alegria, paz, longanimidade, benignidade, bondade, fidelidade, mansidão, domínio próprio.\"* (Gálatas 5:22-23)\nFruto não aparece no dia seguinte ao plantio. Mas aparece."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Vai ter luta. *\"A nossa luta não é contra o sangue e a carne, e sim contra… as forças espirituais do mal.\"* (Efésios 6:12) Por isso Deus dá armadura: verdade, justiça, fé, salvação, a Palavra (Efésios 6:14-17). Você não briga desarmado(a)."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "Como o ramo dá fruto, segundo João 15:5?\nA) Se esforçando muito\nB) Permanecendo ligado à videira ✅\nC) Sozinho\n*(Explicação: \"sem mim nada podeis fazer\".)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Consultório de Família (Novo Tempo) — \"Quando o outro não quer mudar\": sobre transformação que não se força.\nhttps://www.youtube.com/watch?v=A7PgC6nQByw\n\nVocê concluiu o Bloco III — *Jesus*. 🌱 Selo \"Jesus\" + 400 pontos. Faltam dois blocos. O próximo, \"Uma vida inteira\", é sobre corpo, descanso, família e pertencer a algum lugar.\n\nOração: \"Jesus, me mantém ligado(a) ao Senhor. Eu não dou conta de produzir fruto sozinho(a).\"", "opcoes": ["Quero começar o Bloco IV", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero começar o Bloco IV", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=A7PgC6nQByw"]'::jsonb, 'Estudo 13 "Jesus e o Crescimento Espiritual" (João 15:1-14; Colossenses 1:13-14; 2 Coríntios 5:17; Gálatas 5:22-23; Efésios 6:12-17)', NULL)
