insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (13, 4, 'corpo-mente-e-espirito-o-cuidado-de-deus-com-a-pessoa-inteir', 'Corpo, mente e espírito: o cuidado de Deus com a pessoa inteira', 'Saúde, vícios', 5, '[nome], Bloco IV. Deus não se interessa só pela sua "alma". Ele se interessa pelo seu sono, pelo que você come, pelo que passa na sua cabeça às 3 da manhã.

*"Não sabeis que o vosso corpo é santuário do Espírito Santo, que está em vós?… Glorificai, pois, a Deus no vosso corpo."* (1 Coríntios 6:19-20)
Santuário. Não uma casca descartável. Cuidar do corpo é cuidar de algo que Deus habita.

Jesus falou de ansiedade antes de qualquer psicólogo: *"Não andeis ansiosos pela vossa vida, quanto ao que haveis de comer ou beber… Olhai para as aves do céu… vosso Pai celeste as sustenta. Porventura não valeis vós muito mais do que as aves?"* (Mateus 6:25-26)

Para a mente, uma dieta: *"Tudo o que é verdadeiro, tudo o que é respeitável, tudo o que é justo, tudo o que é puro, tudo o que é amável… seja isso o que ocupe o vosso pensamento."* (Filipenses 4:8)
O que a gente consome de madrugada no celular também alimenta — ou envenena.

Por isso a igreja adventista fala de água, sono, ar puro, comida de verdade (Gênesis 1:29), movimento, e de ficar longe do que escraviza — álcool, cigarro, drogas (1 Coríntios 3:16-17). Não é regra para ganhar o céu. É cuidado com o santuário. O princípio: *"Fazei tudo para a glória de Deus."* (1 Coríntios 10:31)

Escolha UMA coisa pequena para esta semana: dormir 30 min mais cedo · caminhar 15 min · trocar um refrigerante por água · deixar o celular fora do quarto. Me diz qual.

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Cuidado com o Corpo":
https://www.youtube.com/watch?v=vTXkFycYxao
🎥 Consultório de Família — "Superando uma doença emocional":
https://www.youtube.com/watch?v=swPyOIc-DxE

Se você luta com álcool ou outra dependência, não está sozinho(a) nisso também: me escreva e uma pessoa da igreja vai te indicar ajuda de verdade.', '[]'::jsonb, NULL, 'https://www.youtube.com/watch?v=vTXkFycYxao', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], Bloco IV. Deus não se interessa só pela sua \"alma\". Ele se interessa pelo seu sono, pelo que você come, pelo que passa na sua cabeça às 3 da manhã."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "*\"Não sabeis que o vosso corpo é santuário do Espírito Santo, que está em vós?… Glorificai, pois, a Deus no vosso corpo.\"* (1 Coríntios 6:19-20)\nSantuário. Não uma casca descartável. Cuidar do corpo é cuidar de algo que Deus habita."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "Jesus falou de ansiedade antes de qualquer psicólogo: *\"Não andeis ansiosos pela vossa vida, quanto ao que haveis de comer ou beber… Olhai para as aves do céu… vosso Pai celeste as sustenta. Porventura não valeis vós muito mais do que as aves?\"* (Mateus 6:25-26)"}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "Para a mente, uma dieta: *\"Tudo o que é verdadeiro, tudo o que é respeitável, tudo o que é justo, tudo o que é puro, tudo o que é amável… seja isso o que ocupe o vosso pensamento.\"* (Filipenses 4:8)\nO que a gente consome de madrugada no celular também alimenta — ou envenena."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Por isso a igreja adventista fala de água, sono, ar puro, comida de verdade (Gênesis 1:29), movimento, e de ficar longe do que escraviza — álcool, cigarro, drogas (1 Coríntios 3:16-17). Não é regra para ganhar o céu. É cuidado com o santuário. O princípio: *\"Fazei tudo para a glória de Deus.\"* (1 Coríntios 10:31)"}, {"n": 6, "tipo": "exercicio", "rotulo": "exercício (100 pontos)", "texto": "Escolha UMA coisa pequena para esta semana: dormir 30 min mais cedo · caminhar 15 min · trocar um refrigerante por água · deixar o celular fora do quarto. Me diz qual.", "opcoes": ["Sono", "Caminhada", "Água", "Celular"]}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Cuidado com o Corpo\":\nhttps://www.youtube.com/watch?v=vTXkFycYxao\n🎥 Consultório de Família — \"Superando uma doença emocional\":\nhttps://www.youtube.com/watch?v=swPyOIc-DxE\n\nSe você luta com álcool ou outra dependência, não está sozinho(a) nisso também: me escreva e uma pessoa da igreja vai te indicar ajuda de verdade.", "opcoes": ["Quero a lição 14", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 14", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=vTXkFycYxao", "https://www.youtube.com/watch?v=swPyOIc-DxE"]'::jsonb, 'Estudo 16 "Jesus e o Estilo de Vida Cristão" (Mateus 6:25-34; 1 Coríntios 10:31; 1 Coríntios 6:19-20; Filipenses 4:8; Gênesis 1:29; 1 Coríntios 3:16-17)', 'Escolha UMA coisa pequena para esta semana: dormir 30 min mais cedo · caminhar 15 min · trocar um refrigerante por água · deixar o celular fora do quarto. Me diz qual.')
