insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (14, 4, 'o-sabado-o-descanso-que-cura', 'O sábado: o descanso que cura', 'Sobrecarga', 5, '[nome], você vive cansado(a)? Deus previu isso. Antes de existir pecado, trabalho pesado ou boleto, Ele criou uma coisa: um dia inteiro para parar.

*"E, havendo Deus terminado no dia sétimo a sua obra… descansou… E abençoou Deus o dia sétimo e o santificou."* (Gênesis 2:2-3)
Deus não estava cansado. Estava dando o exemplo: parar faz parte de viver.

Jesus explicou para que serve: *"O sábado foi estabelecido por causa do homem, e não o homem por causa do sábado."* (Marcos 2:27)
Não é uma prova de obediência. É um presente. Feito para você.

E Ele mostrou como se usa. Num sábado, curou um homem com a mão seca enquanto os religiosos reclamavam. Resposta: *"É lícito, nos sábados, fazer o bem."* (Mateus 12:12) Sábado é dia de cura, de gente, de Deus. Era o costume de Jesus ir à sinagoga (Lucas 4:16); Seus discípulos guardaram o sábado mesmo depois da cruz (Lucas 23:56); Paulo também (Atos 17:2).

Por que a igreja adventista guarda o sábado (do pôr do sol de sexta ao pôr do sol de sábado)? Porque é o dia que Deus abençoou, o quarto mandamento (Êxodo 20:8-11), e o dia que Jesus chamou de Seu: *"O Filho do Homem é senhor do sábado."* (Mateus 12:8) E vai existir na eternidade (Isaías 66:23). Para quem vive exausto, é o remédio mais antigo do mundo: 24 horas sem ter que produzir nada.

Para quem o sábado foi feito, segundo Marcos 2:27?
A) Para os religiosos
B) Para o ser humano ✅
C) Para Deus descansar
*(Explicação: "por causa do homem" — é presente para você.)*

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Sábado":
https://www.youtube.com/watch?v=_XTfOtCGsFg
🎧 Rádio Novo Tempo — "O que Jesus ensinou sobre o sábado":
https://www.youtube.com/watch?v=rWAj1u7ZoAs

Convite sem pressão: a igreja Nova Esperança se reúne aos sábados pela manhã. Se um dia quiser conhecer, a gente te busca. Se não quiser, continua aqui comigo.', '[{"pergunta": "Para quem o sábado foi feito, segundo Marcos 2:27?", "alternativas": ["Para os religiosos", "Para o ser humano", "Para Deus descansar"], "correta": 1, "explicacao": "\"por causa do homem\" — é presente para você."}]'::jsonb, NULL, 'https://www.youtube.com/watch?v=_XTfOtCGsFg', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], você vive cansado(a)? Deus previu isso. Antes de existir pecado, trabalho pesado ou boleto, Ele criou uma coisa: um dia inteiro para parar."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "*\"E, havendo Deus terminado no dia sétimo a sua obra… descansou… E abençoou Deus o dia sétimo e o santificou.\"* (Gênesis 2:2-3)\nDeus não estava cansado. Estava dando o exemplo: parar faz parte de viver."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "Jesus explicou para que serve: *\"O sábado foi estabelecido por causa do homem, e não o homem por causa do sábado.\"* (Marcos 2:27)\nNão é uma prova de obediência. É um presente. Feito para você."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "E Ele mostrou como se usa. Num sábado, curou um homem com a mão seca enquanto os religiosos reclamavam. Resposta: *\"É lícito, nos sábados, fazer o bem.\"* (Mateus 12:12) Sábado é dia de cura, de gente, de Deus. Era o costume de Jesus ir à sinagoga (Lucas 4:16); Seus discípulos guardaram o sábado mesmo depois da cruz (Lucas 23:56); Paulo também (Atos 17:2)."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Por que a igreja adventista guarda o sábado (do pôr do sol de sexta ao pôr do sol de sábado)? Porque é o dia que Deus abençoou, o quarto mandamento (Êxodo 20:8-11), e o dia que Jesus chamou de Seu: *\"O Filho do Homem é senhor do sábado.\"* (Mateus 12:8) E vai existir na eternidade (Isaías 66:23). Para quem vive exausto, é o remédio mais antigo do mundo: 24 horas sem ter que produzir nada."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "Para quem o sábado foi feito, segundo Marcos 2:27?\nA) Para os religiosos\nB) Para o ser humano ✅\nC) Para Deus descansar\n*(Explicação: \"por causa do homem\" — é presente para você.)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Sábado\":\nhttps://www.youtube.com/watch?v=_XTfOtCGsFg\n🎧 Rádio Novo Tempo — \"O que Jesus ensinou sobre o sábado\":\nhttps://www.youtube.com/watch?v=rWAj1u7ZoAs\n\nConvite sem pressão: a igreja Nova Esperança se reúne aos sábados pela manhã. Se um dia quiser conhecer, a gente te busca. Se não quiser, continua aqui comigo.", "opcoes": ["Quero a lição 15", "Quero conhecer a igreja", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 15", "Quero conhecer a igreja", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=_XTfOtCGsFg", "https://www.youtube.com/watch?v=rWAj1u7ZoAs"]'::jsonb, 'Estudo 11 "Jesus e o Sábado" (Mateus 12:9-14; Mateus 12:8, 12; Marcos 2:27; Lucas 4:16; Lucas 23:52-56; Atos 17:2; Isaías 66:22-23) + Gênesis 2:2-3; Êxodo 20:8-11', NULL)
