insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (15, 4, 'familia-relacionamentos-e-dinheiro-a-luz-da-biblia', 'Família, relacionamentos e dinheiro à luz da Bíblia', 'Conflitos, pressão', 5, '[nome], as três coisas que mais tiram o sono: família, relacionamentos e dinheiro. A Bíblia fala das três sem rodeio.

*Relacionamentos.* *"Falai a verdade cada um com o seu próximo."* (Efésios 4:25) *"Se alguém for surpreendido nalguma falta, vós, que sois espirituais, corrigi-o com espírito de brandura."* (Gálatas 6:1) Verdade com brandura. A maioria das brigas falha em um dos dois.

*Família.* O modelo bíblico de casamento é amor que se entrega: *"Maridos, amai vossa mulher, como também Cristo amou a igreja e a si mesmo se entregou por ela."* (Efésios 5:25) Não é sobre quem manda. É sobre quem serve primeiro.

*Dinheiro.* Jesus contou de um senhor que confiou recursos a servos e esperou fidelidade (Lucas 19:11-27). O princípio: *"Buscai, pois, em primeiro lugar, o seu reino e a sua justiça, e todas estas coisas vos serão acrescentadas."* (Mateus 6:33) E a lembrança: *"É o Senhor, teu Deus, que te dá força para adquirires riquezas."* (Deuteronômio 8:18)

Por isso o cristão devolve a Deus o dízimo (10%) e dá ofertas — não para comprar bênção, mas como quem reconhece de onde tudo vem: *"Trazei todos os dízimos à casa do Tesouro… e provai-me nisto, diz o Senhor dos Exércitos."* (Malaquias 3:10) *"Deus ama a quem dá com alegria."* (2 Coríntios 9:7) Jesus elogiou uma viúva que deu duas moedinhas — porque deu com o coração (Marcos 12:41-44). O valor é o coração, não a cifra.

O que Jesus mais valorizou na oferta da viúva (Marcos 12:41-44)?
A) O valor em dinheiro
B) O coração com que ela deu ✅
C) O fato de todos verem
*(Explicação: ela deu "tudo quanto possuía".)*

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Dinheiro":
https://www.youtube.com/watch?v=NozIcqBLWPs
🎧 Consultório de Família (rádio Novo Tempo) — programa diário sobre casamento, filhos e relacionamentos, com psicólogos e pastores:
https://www.novotempo.com/programa/consultoriodefamiliaradio/

Se a sua casa está em crise, me conta. Uma pessoa da igreja pode orar com você e indicar aconselhamento familiar.', '[{"pergunta": "O que Jesus mais valorizou na oferta da viúva (Marcos 12:41-44)?", "alternativas": ["O valor em dinheiro", "O coração com que ela deu", "O fato de todos verem"], "correta": 1, "explicacao": "ela deu \"tudo quanto possuía\"."}]'::jsonb, NULL, 'https://www.youtube.com/watch?v=NozIcqBLWPs', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], as três coisas que mais tiram o sono: família, relacionamentos e dinheiro. A Bíblia fala das três sem rodeio."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "*Relacionamentos.* *\"Falai a verdade cada um com o seu próximo.\"* (Efésios 4:25) *\"Se alguém for surpreendido nalguma falta, vós, que sois espirituais, corrigi-o com espírito de brandura.\"* (Gálatas 6:1) Verdade com brandura. A maioria das brigas falha em um dos dois."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "*Família.* O modelo bíblico de casamento é amor que se entrega: *\"Maridos, amai vossa mulher, como também Cristo amou a igreja e a si mesmo se entregou por ela.\"* (Efésios 5:25) Não é sobre quem manda. É sobre quem serve primeiro."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "*Dinheiro.* Jesus contou de um senhor que confiou recursos a servos e esperou fidelidade (Lucas 19:11-27). O princípio: *\"Buscai, pois, em primeiro lugar, o seu reino e a sua justiça, e todas estas coisas vos serão acrescentadas.\"* (Mateus 6:33) E a lembrança: *\"É o Senhor, teu Deus, que te dá força para adquirires riquezas.\"* (Deuteronômio 8:18)"}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Por isso o cristão devolve a Deus o dízimo (10%) e dá ofertas — não para comprar bênção, mas como quem reconhece de onde tudo vem: *\"Trazei todos os dízimos à casa do Tesouro… e provai-me nisto, diz o Senhor dos Exércitos.\"* (Malaquias 3:10) *\"Deus ama a quem dá com alegria.\"* (2 Coríntios 9:7) Jesus elogiou uma viúva que deu duas moedinhas — porque deu com o coração (Marcos 12:41-44). O valor é o coração, não a cifra."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "O que Jesus mais valorizou na oferta da viúva (Marcos 12:41-44)?\nA) O valor em dinheiro\nB) O coração com que ela deu ✅\nC) O fato de todos verem\n*(Explicação: ela deu \"tudo quanto possuía\".)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Dinheiro\":\nhttps://www.youtube.com/watch?v=NozIcqBLWPs\n🎧 Consultório de Família (rádio Novo Tempo) — programa diário sobre casamento, filhos e relacionamentos, com psicólogos e pastores:\nhttps://www.novotempo.com/programa/consultoriodefamiliaradio/\n\nSe a sua casa está em crise, me conta. Uma pessoa da igreja pode orar com você e indicar aconselhamento familiar.", "opcoes": ["Quero a lição 16", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 16", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=NozIcqBLWPs", "https://www.novotempo.com/programa/consultoriodefamiliaradio/"]'::jsonb, 'Estudo 14 "Jesus e a Fidelidade" (Lucas 19:11-27; Mateus 6:33; Deuteronômio 8:17-18; Malaquias 3:10; 2 Coríntios 9:7; Marcos 12:41-44) + Estudo 16 (Efésios 5:22-25; Efésios 4:25; Gálatas 6:1)', NULL)
