insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (16, 4, 'a-igreja-uma-familia-para-quem-nao-tem', 'A igreja: uma família para quem não tem', 'Pertencimento', 5, '[nome], última lição do Bloco IV. Muita gente diz: "eu creio em Deus, mas igreja não é para mim." Entendo. Mas deixa eu te mostrar o que a Bíblia chama de igreja — não é o prédio.

*"Assim, já não sois estrangeiros e peregrinos, mas concidadãos dos santos, e sois da família de Deus."* (Efésios 2:19)
Família. Para quem a família de sangue falhou, Deus oferece outra. Com fundamento em Cristo (Efésios 2:20) — não em pessoas, que erram.

A imagem de Paulo: *"Assim como o corpo é um e tem muitos membros… assim também com respeito a Cristo."* (1 Coríntios 12:12) Um corpo. Ninguém é sobra. Ninguém é só espectador.

Para que serve? *"Vós, porém, sois raça eleita… povo de propriedade exclusiva de Deus, a fim de proclamardes as virtudes daquele que vos chamou das trevas para a sua maravilhosa luz."* (1 Pedro 2:9)
Quem saiu do escuro conta para quem ainda está lá. Esse projeto — A Chave da Virada — é exatamente isso.

A marca da igreja de Deus nos últimos dias: *"Aqui está a perseverança dos santos, os que guardam os mandamentos de Deus e a fé em Jesus."* (Apocalipse 14:12) E a marca de quem é dEle: *"Nisto conhecerão todos que sois meus discípulos: se tiverdes amor uns aos outros."* (João 13:35)
Igreja é hospital, não vitrine. Chega quem está machucado.

Segundo João 13:35, como se reconhece um discípulo de Jesus?
A) Pela roupa
B) Pelo amor uns aos outros ✅
C) Pelo prédio que frequenta
*(Explicação: "nisto conhecerão todos".)*

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Igreja":
https://www.youtube.com/watch?v=N-pRH0PHZB4

Você concluiu o Bloco IV — *Uma vida inteira*. 🌱 Selo "Vida Inteira" + 400 pontos. Último bloco: "O futuro" — os Dez Mandamentos, a morte, a volta de Jesus e a decisão.

Convite: no próximo sábado tem culto na Nova Esperança. Se quiser ir, uma pessoa te busca e senta do seu lado. Sem ter que fazer nada.', '[{"pergunta": "Segundo João 13:35, como se reconhece um discípulo de Jesus?", "alternativas": ["Pela roupa", "Pelo amor uns aos outros", "Pelo prédio que frequenta"], "correta": 1, "explicacao": "\"nisto conhecerão todos\"."}]'::jsonb, NULL, 'https://www.youtube.com/watch?v=N-pRH0PHZB4', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], última lição do Bloco IV. Muita gente diz: \"eu creio em Deus, mas igreja não é para mim.\" Entendo. Mas deixa eu te mostrar o que a Bíblia chama de igreja — não é o prédio."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "*\"Assim, já não sois estrangeiros e peregrinos, mas concidadãos dos santos, e sois da família de Deus.\"* (Efésios 2:19)\nFamília. Para quem a família de sangue falhou, Deus oferece outra. Com fundamento em Cristo (Efésios 2:20) — não em pessoas, que erram."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "A imagem de Paulo: *\"Assim como o corpo é um e tem muitos membros… assim também com respeito a Cristo.\"* (1 Coríntios 12:12) Um corpo. Ninguém é sobra. Ninguém é só espectador."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "Para que serve? *\"Vós, porém, sois raça eleita… povo de propriedade exclusiva de Deus, a fim de proclamardes as virtudes daquele que vos chamou das trevas para a sua maravilhosa luz.\"* (1 Pedro 2:9)\nQuem saiu do escuro conta para quem ainda está lá. Esse projeto — A Chave da Virada — é exatamente isso."}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "A marca da igreja de Deus nos últimos dias: *\"Aqui está a perseverança dos santos, os que guardam os mandamentos de Deus e a fé em Jesus.\"* (Apocalipse 14:12) E a marca de quem é dEle: *\"Nisto conhecerão todos que sois meus discípulos: se tiverdes amor uns aos outros.\"* (João 13:35)\nIgreja é hospital, não vitrine. Chega quem está machucado."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "Segundo João 13:35, como se reconhece um discípulo de Jesus?\nA) Pela roupa\nB) Pelo amor uns aos outros ✅\nC) Pelo prédio que frequenta\n*(Explicação: \"nisto conhecerão todos\".)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Igreja\":\nhttps://www.youtube.com/watch?v=N-pRH0PHZB4\n\nVocê concluiu o Bloco IV — *Uma vida inteira*. 🌱 Selo \"Vida Inteira\" + 400 pontos. Último bloco: \"O futuro\" — os Dez Mandamentos, a morte, a volta de Jesus e a decisão.\n\nConvite: no próximo sábado tem culto na Nova Esperança. Se quiser ir, uma pessoa te busca e senta do seu lado. Sem ter que fazer nada.", "opcoes": ["Quero começar o Bloco V", "Quero ir no sábado", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero começar o Bloco V", "Quero ir no sábado", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=N-pRH0PHZB4"]'::jsonb, 'Estudo 12 "Jesus e a Igreja" (Lucas 13:22-30; Mateus 16:16-18; Efésios 2:19-20; 1 Pedro 2:9; 1 Coríntios 12:12-13, 20; Apocalipse 14:12; Mateus 28:18-20) + Estudo 17 "Jesus e a Missão" (Lucas 5:1-11; Atos 1:8; João 13:34-35)', NULL)
on conflict (numero) do update set bloco=excluded.bloco, slug=excluded.slug, titulo=excluded.titulo, necessidade=excluded.necessidade, corpo_md=excluded.corpo_md, quiz=excluded.quiz, oracao=excluded.oracao, video_url=excluded.video_url, pontos=excluded.pontos, publicado=true, mensagens=excluded.mensagens, botoes=excluded.botoes, videos=excluded.videos, fonte=excluded.fonte, exercicio=excluded.exercicio;
insert into estudos (numero, bloco, slug, titulo, necessidade, tempo_leitura, corpo_md, quiz, oracao, video_url, pontos, publicado, mensagens, botoes, videos, fonte, exercicio) values (17, 5, 'os-dez-mandamentos-o-amor-em-dez-frases', 'Os Dez Mandamentos: o amor em dez frases', 'Direção', 5, '[nome], Bloco V, o último. Começamos pela pergunta: a lei de Deus é um conjunto de proibições ou um mapa? Jesus respondeu com uma casa.

*"Todo aquele que ouve estas minhas palavras e as pratica será comparado a um homem prudente que edificou a sua casa sobre a rocha."* (Mateus 7:24) Veio chuva, vento, enchente — a casa ficou. A lei de Deus é a rocha debaixo da sua vida, não a grade em volta dela.

Perguntaram a Jesus qual o maior mandamento. Ele resumiu os dez em dois: *"Amarás o Senhor, teu Deus, de todo o teu coração… Amarás o teu próximo como a ti mesmo."* (Mateus 22:37-39) Os quatro primeiros (Êxodo 20:3-11) são sobre amar a Deus. Os seis últimos (20:12-17), sobre amar gente. É amor em dez frases.

Jesus não aboliu nada: *"Até que o céu e a terra passem, nem um i ou um til jamais passará da Lei."* (Mateus 5:18) E ligou obediência a amor, não a medo: *"Se me amais, guardareis os meus mandamentos."* (João 14:15)

Mas atenção: a lei não salva. Ela mostra o problema — *"o pecado é a transgressão da lei"* (1 João 3:4) — e aponta para quem resolve: *"A lei nos serviu de aio para nos conduzir a Cristo."* (Gálatas 3:24) Somos *"justificados gratuitamente, por sua graça"* (Romanos 3:24). Guardar a lei é a resposta de quem já foi salvo, não o preço para ser.

Em que Jesus resumiu os Dez Mandamentos (Mateus 22:37-39)?
A) Em muitas regras novas
B) Em amar a Deus e amar o próximo ✅
C) Em não fazer nada no sábado
*(Explicação: amor em dez frases.)*

🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema "Lei":
https://www.youtube.com/watch?v=wcBQx9gcnp0

Oração: "Deus, eu quero construir na rocha. Me ensina a amar o Senhor e as pessoas do jeito que a Sua lei descreve."', '[{"pergunta": "Em que Jesus resumiu os Dez Mandamentos (Mateus 22:37-39)?", "alternativas": ["Em muitas regras novas", "Em amar a Deus e amar o próximo", "Em não fazer nada no sábado"], "correta": 1, "explicacao": "amor em dez frases."}]'::jsonb, 'Deus, eu quero construir na rocha. Me ensina a amar o Senhor e as pessoas do jeito que a Sua lei descreve.', 'https://www.youtube.com/watch?v=wcBQx9gcnp0', 100, true, '[{"n": 1, "tipo": "texto", "rotulo": "", "texto": "[nome], Bloco V, o último. Começamos pela pergunta: a lei de Deus é um conjunto de proibições ou um mapa? Jesus respondeu com uma casa."}, {"n": 2, "tipo": "texto", "rotulo": "", "texto": "*\"Todo aquele que ouve estas minhas palavras e as pratica será comparado a um homem prudente que edificou a sua casa sobre a rocha.\"* (Mateus 7:24) Veio chuva, vento, enchente — a casa ficou. A lei de Deus é a rocha debaixo da sua vida, não a grade em volta dela."}, {"n": 3, "tipo": "texto", "rotulo": "", "texto": "Perguntaram a Jesus qual o maior mandamento. Ele resumiu os dez em dois: *\"Amarás o Senhor, teu Deus, de todo o teu coração… Amarás o teu próximo como a ti mesmo.\"* (Mateus 22:37-39) Os quatro primeiros (Êxodo 20:3-11) são sobre amar a Deus. Os seis últimos (20:12-17), sobre amar gente. É amor em dez frases."}, {"n": 4, "tipo": "texto", "rotulo": "", "texto": "Jesus não aboliu nada: *\"Até que o céu e a terra passem, nem um i ou um til jamais passará da Lei.\"* (Mateus 5:18) E ligou obediência a amor, não a medo: *\"Se me amais, guardareis os meus mandamentos.\"* (João 14:15)"}, {"n": 5, "tipo": "texto", "rotulo": "", "texto": "Mas atenção: a lei não salva. Ela mostra o problema — *\"o pecado é a transgressão da lei\"* (1 João 3:4) — e aponta para quem resolve: *\"A lei nos serviu de aio para nos conduzir a Cristo.\"* (Gálatas 3:24) Somos *\"justificados gratuitamente, por sua graça\"* (Romanos 3:24). Guardar a lei é a resposta de quem já foi salvo, não o preço para ser."}, {"n": 6, "tipo": "quiz", "rotulo": "quiz (100 pontos)", "texto": "Em que Jesus resumiu os Dez Mandamentos (Mateus 22:37-39)?\nA) Em muitas regras novas\nB) Em amar a Deus e amar o próximo ✅\nC) Em não fazer nada no sábado\n*(Explicação: amor em dez frases.)*"}, {"n": 7, "tipo": "fechamento", "rotulo": "vídeo e fechamento", "texto": "🎥 Bíblia Fácil (Novo Tempo) — Ensinos de Jesus, tema \"Lei\":\nhttps://www.youtube.com/watch?v=wcBQx9gcnp0\n\nOração: \"Deus, eu quero construir na rocha. Me ensina a amar o Senhor e as pessoas do jeito que a Sua lei descreve.\"", "opcoes": ["Quero a lição 18", "Quero que orem por mim", "Quero falar com uma pessoa"]}]'::jsonb, '["Quero a lição 18", "Quero que orem por mim", "Quero falar com uma pessoa"]'::jsonb, '["https://www.youtube.com/watch?v=wcBQx9gcnp0"]'::jsonb, 'Estudo 10 "Jesus e a Lei de Deus" (Mateus 7:24-27; Mateus 22:36-40; João 15:10; Gálatas 3:24; João 14:15; Mateus 5:18-19; 1 João 3:4; Tiago 2:10; Romanos 3:23-24) + Êxodo 20:3-17', NULL)
