-- Soma pontos de forma atômica (chamado pelo robô)
create or replace function somar_pontos(p_pessoa uuid, p_delta int) returns void language sql as $$
  update pessoas set pontos = pontos + p_delta where id = p_pessoa
$$;

-- Robô no site: sessão anônima por cookie
alter table pessoas add column if not exists sessao_site text unique;
